//! Clerk-backed external authentication for ONYX.\n//!\n//! Clerk authenticates the human identity. ONYX remains the authorization\n//! authority: the verified Clerk subject is mapped to a local ONYX identity\n//! and receives the normal ONYX access token.\n\nuse axum::{extract::State, http::{HeaderMap, StatusCode}, Json};\nuse jsonwebtoken::{decode, decode_header, Algorithm, DecodingKey, Validation};\nuse serde::{Deserialize, Serialize};\nuse serde_json::json;\nuse security_application::{NewUser, UserStore};\n\nuse super::{issue_token, ApiError, ApiState, LoginResponse, LoginUser};\nuse crate::routes::client_type::ClientType;\n\npub const ALLFATHER_USERNAME: &str = "Allfather";\nconst CLERK_USERNAME_PREFIX: &str = "clerk:";\n\n#[derive(Debug, Clone)]\npub struct ClerkAuth {\n    jwt_key: DecodingKey,\n    issuer: String,\n    allfather_user_id: String,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\nstruct ClerkClaims {\n    sub: String,\n    iss: String,\n    exp: usize,\n    iat: usize,\n    #[serde(default)] nbf: Option<usize>,\n    #[serde(default)] sts: Option<String>,\n}\n\n#[derive(Debug, Clone)]\npub struct ClerkPrincipal {\n    pub subject: String,\n}\n\nimpl ClerkAuth {\n    pub fn from_env() -> anyhow::Result<Option<Self>> {\n        let key = std::env::var("CLERK_JWT_KEY").ok();\n        let issuer = std::env::var("CLERK_ISSUER").ok();\n        let allfather = std::env::var("CLERK_ALLFATHER_USER_ID").ok();\n        if key.is_none() && issuer.is_none() && allfather.is_none() { return Ok(None); }\n        let key = key.ok_or_else(|| anyhow::anyhow!("CLERK_JWT_KEY is required when Clerk is configured"))?;\n        let issuer = issuer.ok_or_else(|| anyhow::anyhow!("CLERK_ISSUER is required when Clerk is configured"))?;\n        let allfather_user_id = allfather.ok_or_else(|| anyhow::anyhow!("CLERK_ALLFATHER_USER_ID is required when Clerk is configured"))?;\n        let jwt_key = DecodingKey::from_rsa_pem(key.as_bytes()).map_err(|error| anyhow::anyhow!("invalid CLERK_JWT_KEY PEM: {error}"))?;\n        Ok(Some(Self { jwt_key, issuer, allfather_user_id }))\n    }\n\n    pub fn verify_headers(&self, headers: &HeaderMap) -> Result<ClerkPrincipal, ApiError> {\n        let token = headers.get(axum::http::header::AUTHORIZATION).and_then(|v| v.to_str().ok()).and_then(|v| v.strip_prefix("Bearer ")).ok_or_else(|| ApiError::unauthorized(uuid::Uuid::new_v4().to_string()))?;\n        let header = decode_header(token).map_err(|_| ApiError::unauthorized(uuid::Uuid::new_v4().to_string()))?;\n        if header.alg != Algorithm::RS256 { return Err(ApiError::unauthorized(uuid::Uuid::new_v4().to_string())); }\n        let mut validation = Validation::new(Algorithm::RS256);\n        validation.set_issuer(&[self.issuer.as_str()]);\n        validation.leeway = 5;\n        validation.validate_nbf = true;\n        let decoded = decode::<ClerkClaims>(token, &self.jwt_key, &validation).map_err(|_| ApiError::unauthorized(uuid::Uuid::new_v4().to_string()))?;\n        if decoded.claims.sub.trim().is_empty() || decoded.claims.iss != self.issuer || decoded.claims.sts.as_deref() == Some("pending") { return Err(ApiError::unauthorized(uuid::Uuid::new_v4().to_string())); }\n        Ok(ClerkPrincipal { subject: decoded.claims.sub })\n    }\n\n    pub fn is_allfather(&self, principal: &ClerkPrincipal) -> bool { principal.subject == self.allfather_user_id }\n    pub fn mapped_username(subject: &str) -> String { format!("{CLERK_USERNAME_PREFIX}{subject}") }\n}\n\npub async fn exchange(State(state): State<ApiState>, headers: HeaderMap) -> Result<Json<LoginResponse>, ApiError> {\n    let clerk = state.clerk_auth.as_ref().ok_or_else(|| ApiError::new(StatusCode::NOT_IMPLEMENTED, "CLERK_AUTH_NOT_CONFIGURED", "AUTHORITY", "NON_RETRYABLE", uuid::Uuid::new_v4().to_string(), json!({"message":"Clerk authentication is not configured"})))?;\n    let principal = clerk.verify_headers(&headers)?;\n    let username = ClerkAuth::mapped_username(&principal.subject);\n    let user = state.user_store.find_by_username(&username).await.map_err(|error| {\n        tracing::error!(error = %error, "Clerk identity lookup failed");\n        ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "USER_STORE_UNAVAILABLE", "INFRASTRUCTURE", "TRANSIENT", uuid::Uuid::new_v4().to_string(), json!({}))\n    })?.filter(|user| user.is_active).ok_or_else(|| ApiError::new(StatusCode::FORBIDDEN, "CLERK_IDENTITY_NOT_LINKED", "AUTHORITY", "NON_RETRYABLE", uuid::Uuid::new_v4().to_string(), json!({"message":"The authenticated Clerk identity is not linked to an ONYX account"})))?;\n    issue_clerk_session(&state, user, ClientType::Web).await\n}\n\npub async fn bootstrap(State(state): State<ApiState>, headers: HeaderMap) -> Result<Json<LoginResponse>, ApiError> {\n    let clerk = state.clerk_auth.as_ref().ok_or_else(|| ApiError::new(StatusCode::NOT_IMPLEMENTED, "CLERK_AUTH_NOT_CONFIGURED", "AUTHORITY", "NON_RETRYABLE", uuid::Uuid::new_v4().to_string(), json!({"message":"Clerk authentication is not configured"})))?;\n    let principal = clerk.verify_headers(&headers)?;\n    if !clerk.is_allfather(&principal) { return Err(ApiError::new(StatusCode::FORBIDDEN, "ALLFATHER_REQUIRED", "AUTHORITY", "NON_RETRYABLE", uuid::Uuid::new_v4().to_string(), json!({"message":"Only the configured Allfather identity may perform first-run bootstrap"}))); }\n    let count = state.user_store.count().await.map_err(|error| {\n        tracing::error!(error = %error, "user store count failed during Clerk bootstrap");\n        ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "USER_STORE_UNAVAILABLE", "INFRASTRUCTURE", "TRANSIENT", uuid::Uuid::new_v4().to_string(), json!({}))\n    })?;\n    if count != 0 { return Err(ApiError::new(StatusCode::CONFLICT, "BOOTSTRAP_ALREADY_COMPLETED", "AUTHORITY", "NON_RETRYABLE", uuid::Uuid::new_v4().to_string(), json!({"message":"ONYX already has an identity; Clerk bootstrap is permanently closed"}))); }\n    let random_password = format!("clerk-bootstrap-{}-{}", uuid::Uuid::new_v4(), uuid::Uuid::new_v4());\n    let password_hash = state.password_hasher.hash(&random_password).map_err(|error| {\n        tracing::error!(error = %error, "failed to create local credential for Allfather");\n        ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "CREDENTIAL_INITIALIZATION_FAILED", "INFRASTRUCTURE", "NON_RETRYABLE", uuid::Uuid::new_v4().to_string(), json!({}))\n    })?;\n    let user = state.user_store.create(NewUser {\n        user_id: uuid::Uuid::new_v4().to_string(),\n        username: ClerkAuth::mapped_username(&principal.subject),\n        organization_id: super::ORGANIZATION_ID.to_string(),\n        password_hash, is_admin: true, is_manager: false, class: None, parent_user_id: None,\n    }).await.map_err(|error| {\n        tracing::error!(error = %error, "failed to create Allfather identity");\n        ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "BOOTSTRAP_FAILED", "INFRASTRUCTURE", "NON_RETRYABLE", uuid::Uuid::new_v4().to_string(), json!({}))\n    })?;\n    tracing::warn!(user_id = %user.user_id, clerk_subject = %principal.subject, "Allfather Clerk bootstrap completed; Clerk identity is now bound to ONYX");\n    issue_clerk_session(&state, user, ClientType::Admin).await\n}\n\nasync fn issue_clerk_session(state: &ApiState, user: security_application::UserRecord, client_type: ClientType) -> Result<Json<LoginResponse>, ApiError> {\n    let access_token = issue_token(state, &user, "access", 3600, client_type).await.map_err(|_| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "TOKEN_ISSUANCE_FAILED", "INFRASTRUCTURE", "TRANSIENT", uuid::Uuid::new_v4().to_string(), json!({})))?;\n    let refresh_token = issue_token(state, &user, "refresh", 7 * 24 * 3600, client_type).await.map_err(|_| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "TOKEN_ISSUANCE_FAILED", "INFRASTRUCTURE", "TRANSIENT", uuid::Uuid::new_v4().to_string(), json!({})))?;\n    Ok(Json(LoginResponse { access_token, refresh_token, expires_in: 3600, user: LoginUser { id: user.user_id, username: user.username, organization_id: user.organization_id, is_admin: user.is_admin, class: user.class.map(|class| class.as_str().to_string()) } }))\n}\n